import type { SVGProps } from "react";

export type VordiaIsotipoProps = Omit<SVGProps<SVGSVGElement>, "children" | "viewBox">;

// Imagen original integrada; el viewport muestra solamente la zona del isotipo.
// Conserva el fondo y los reflejos de la captura. No es un trazado vectorial.
// Uso: <VordiaIsotipo style={{ width: 320, height: "auto" }} />
const SOURCE = "data:image/png;base64,";

export default function VordiaIsotipo({
  style,
  "aria-label": ariaLabel = "Isotipo VORDIA",
  ...props
}: VordiaIsotipoProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      role="img"
      aria-label={ariaLabel}
      width={450}
      height={392}
      {...props}
      viewBox="616 0 450 392"
      style={{ maxWidth: "100%", height: "auto", ...style }}
    >
      <image href={SOURCE} x={0} y={0} width={1214} height={398} />
    </svg>
  );
}
